#include <stdio.h>

struct Student
{
    int   num;
    char  name[10];
    float score;
};

static int find(struct Student a[], int n, int key)
{
    int i;
    for (i = 0; i < n; i++)
        if (a[i].num == key) return i;      /* 返回下标 */
    return -1;
}

int main(void)
{
    struct Student st[4] = {
        {1001, "LiLin", 89.5f},    {1002, "WangFang", 92.0f},
        {1003, "ZhaoLei", 78.5f},  {1004, "SunQi", 85.0f}
    };
    int p1 = find(st, 4, 1003);
    int p2 = find(st, 4, 9999);

    if (p1 >= 0) printf("found at %d: %s %.1f\n", p1, st[p1].name, st[p1].score);
    else         printf("not found\n");
    printf("find(9999) = %d\n", p2);
    return 0;
}

#include <stdio.h>

struct Student
{
    char  name[10];
    float score;
};

static void sort_desc(struct Student a[], int n)
{
    int i, j;
    struct Student t;

    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - 1 - i; j++) {
            if (a[j].score < a[j + 1].score) {
                t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;  /* 整体交换 */
            }
        }
    }
}

int main(void)
{
    struct Student st[5] = {
        {"A", 89.5f}, {"B", 98.5f}, {"C", 92.5f}, {"D", 76.0f}, {"E", 85.0f}
    };
    int i;

    sort_desc(st, 5);
    for (i = 0; i < 5; i++) {
        if (i > 0) printf(" ");
        printf("%s:%.1f", st[i].name, st[i].score);
    }
    printf("\n");
    return 0;
}

