#include <stdio.h>

struct Counter {
    int value;
};

void by_value(struct Counter c)   { c.value++; }
void by_addr(struct Counter *p)   { p->value++; }

void swap_counter(struct Counter *a, struct Counter *b)
{
    struct Counter t = *a;        /* 结构体整体赋值 */
    *a = *b;
    *b = t;
}

int main(void)
{
    struct Counter m = {1}, n = {9};
    by_value(m);
    printf("after by_value: %d\n", m.value);
    by_addr(&m);
    printf("after by_addr : %d\n", m.value);
    swap_counter(&m, &n);
    printf("after swap    : m=%d n=%d\n", m.value, n.value);
    return 0;
}

#include <stdio.h>
