#include <stdio.h>

struct Score {
    int id;
    int val;
};

struct Score *pick_best(struct Score arr[], int n)
{
    int i, k = 0;
    for (i = 1; i < n; i++)
        if (arr[i].val > arr[k].val)
            k = i;
    return &arr[k];            /* 数组属于调用者，返回其元素地址安全 */
}

int main(void)
{
    struct Score a[3] = {{1, 78}, {2, 95}, {3, 88}};
    struct Score *p = pick_best(a, 3);

    printf("best: id=%d val=%d\n", p->id, p->val);
    p->val = 0;                /* 通过指针确实改到了 a[1] */
    printf("a[1].val now = %d\n", a[1].val);
    return 0;
}

#include <stdio.h>
#include <string.h>

struct Student {
    int  num;
    char name[16];
};

static struct Student cache;          /* 静态存储期：函数返回后依然有效 */

struct Student *remember(int num, const char *name)
{
    cache.num = num;
    strcpy(cache.name, name);
    return &cache;                    /* 合法，但只有一份存储 */
}

/* 反面教材，不要这样写：
   struct Student *bad(void) { struct Student t; return &t; }   */

int main(void)
{
    struct Student *p = remember(1001, "Li Lin");
