/* 在第一个值为 a 的结点之前插入 key，找不到 a 则插到表尾 */
void insert_before(struct Node *head, int a, int key)
{
    struct Node *pre = head, *s;

    while (pre->next != NULL && pre->next->data != a)
        pre = pre->next;

    s = (struct Node *)malloc(sizeof(struct Node));
    if (s == NULL)
        return;
    s->data = key;
    s->next = pre->next;
    pre->next = s;
}

