struct Node {
    int data;
    struct Node *next;
};

/* 不带头结点：尾插建表，读到 -1 结束，返回第一个真实结点 */
struct Node *create_list(void)
{
    struct Node *head = NULL, *tail = NULL, *p;
    int x;

    while (scanf("%d", &x) == 1 && x != -1) {
        p = (struct Node *)malloc(sizeof(struct Node));
        if (p == NULL)
            break;
        p->data = x;
        p->next = NULL;
        if (head == NULL)
            head = p;
        else
            tail->next = p;
        tail = p;
    }
    return head;
}

/* 不带头结点：新表头必须返回给调用者 */
struct Node *reverse_list(struct Node *head)
{
    struct Node *pre = NULL, *cur = head, *next;

    while (cur != NULL) {
        next = cur->next;
        cur->next = pre;
        pre = cur;
        cur = next;
    }
    return pre;
}

/* 释放整条链，返回释放的结点数 */
int free_list(struct Node *head)
{
    struct Node *p = head, *q;
    int n = 0;

    while (p != NULL) {
        q = p->next;
        free(p);
        p = q;
        n++;
    }
    return n;
}

void print_list(struct Node *head)
{
    struct Node *p;
    for (p = head; p != NULL; p = p->next)
        printf("%d|", p->data);
    printf("\n");
}

int main(void)
{
    struct Node *head = create_list();
    int n;

    print_list(head);
    head = reverse_list(head);        /* 必须接收返回值 */
    print_list(head);

    n = free_list(head);
    head = NULL;                      /* 释放后置空，避免悬空指针 */
    printf("freed %d nodes\n", n);
    return 0;
}
